import { launch, show } from "../_shared/deno-helpers.ts";
import { BASE_URL, USERS } from "../_shared/deno-helpers.ts";

const { browser, page } = await launch();
await page.goto(BASE_URL);

// These are exactly the locators Codegen would generate if you typed into these
// fields and clicked Login yourself — proven against the live app already.
const email = page.getByPlaceholder("Enter Email");
const password = page.getByPlaceholder("Enter Password");
const loginButton = page.getByRole("button", { name: "Login" });

await email.fill(USERS[0].email);
await password.fill(USERS[0].password);
await loginButton.click();
await page.waitForURL("**/dashboard");

await show(page);
await browser.close();

import { writeProjectFile, REPO_ROOT } from "../_shared/deno-helpers.ts";

const notASpecPath = "week1/generated/day4-not-a-spec.ts";

await writeProjectFile(notASpecPath, `
import { test, expect } from "@playwright/test";

test("this file has no .spec.ts suffix", async ({ page }) => {
  await page.goto("/");
  await expect(page.getByPlaceholder("Enter Email")).toBeVisible();
});
`.trim());

console.log("wrote", notASpecPath);

const NPX = Deno.build.os === "windows" ? "npx.cmd" : "npx";
const cmd = new Deno.Command(NPX, {
  args: ["playwright", "test", "week1/generated", "--list"],
  cwd: REPO_ROOT,
  stdout: "piped",
  stderr: "piped",
});
const { stdout, stderr } = await cmd.output();
console.log(new TextDecoder().decode(stdout) + new TextDecoder().decode(stderr));

// REPO_ROOT and NPX are already imported/declared in the cells above — reused here.
const from = REPO_ROOT + "week1/generated/day4-not-a-spec.ts";
const to = REPO_ROOT + "week1/generated/day4-renamed.spec.ts";
await Deno.rename(from, to);

const cmd2 = new Deno.Command(NPX, {
  args: ["playwright", "test", "week1/generated", "--list"],
  cwd: REPO_ROOT,
  stdout: "piped",
  stderr: "piped",
});
const { stdout: out2 } = await cmd2.output();
console.log(new TextDecoder().decode(out2));

// REPO_ROOT is already imported above — reused here.
await Deno.remove(REPO_ROOT + "week1/generated/day4-renamed.spec.ts");
console.log("cleaned up");

